-- Generated by db:generate, then the role check and grants were added by hand. The one migration
-- that mixes the two (ADR 0011): the generated CREATE POLICY ... TO pulse_mailer needs the role
-- check to run first, so it cannot live in a later custom migration.
-- pulse_mailer comes from infra/compose/postgres/init/04-mailer-role.sql, which only runs on an
-- empty volume; stop here with a clear message instead of a vague policy or GRANT error
DO $$
BEGIN
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'pulse_mailer') THEN
    RAISE EXCEPTION 'role pulse_mailer is missing: run infra/compose/postgres/init/04-mailer-role.sql, or pnpm infra:reset';
  END IF;
END;
$$;
--> statement-breakpoint
CREATE TABLE "email_delivery" (
	"dedupe_key" text PRIMARY KEY NOT NULL,
	"job_id" uuid NOT NULL,
	"template" text NOT NULL,
	"status" text NOT NULL,
	"claim_id" uuid NOT NULL,
	"attempts" integer DEFAULT 1 NOT NULL,
	"last_error" text,
	"claimed_at" timestamp with time zone DEFAULT now() NOT NULL,
	"sent_at" timestamp with time zone,
	CONSTRAINT "email_delivery_status_valid" CHECK ("email_delivery"."status" in ('sending', 'sent', 'failed')),
	CONSTRAINT "email_delivery_sent_at_iff_sent" CHECK (("email_delivery"."status" = 'sent') = ("email_delivery"."sent_at" is not null)),
	CONSTRAINT "email_delivery_attempts_positive" CHECK ("email_delivery"."attempts" >= 1),
	CONSTRAINT "email_delivery_last_error_short" CHECK (length("email_delivery"."last_error") <= 200),
	CONSTRAINT "email_delivery_dedupe_key_short" CHECK (length("email_delivery"."dedupe_key") <= 200),
	CONSTRAINT "email_delivery_template_short" CHECK (length("email_delivery"."template") <= 100)
);
--> statement-breakpoint
CREATE POLICY "campus_mailer_read" ON "campus" AS PERMISSIVE FOR SELECT TO "pulse_mailer" USING (true);
--> statement-breakpoint
GRANT USAGE ON SCHEMA public TO pulse_mailer;
--> statement-breakpoint
-- Claim, mark and read. No DELETE: an erased row would let a redelivered job send again
GRANT SELECT, INSERT, UPDATE ON email_delivery TO pulse_mailer;
--> statement-breakpoint
-- Templates need the campus name, and only that
GRANT SELECT (id, name) ON campus TO pulse_mailer;
--> statement-breakpoint
-- The API sends no email itself. Its default grants (migration 0000) gave it these
REVOKE SELECT, INSERT, UPDATE, DELETE ON email_delivery FROM pulse_app;
